slots := semaphore.NewWeighted(8)        // at most 8 in flight

func handle(ctx context.Context, req Request) error {
    if err := slots.Acquire(ctx, 1); err != nil {
        return err                        // cancelled while waiting
    }
    defer slots.Release(1)                // every exit path frees capacity
    return process(ctx, req)              // else: tryAcquire + shed, if preferred
}

